name: bench-rust
on: push
jobs:
  rust-build-test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Set up Rust
        uses: dtolnay/rust-toolchain@stable
      - name: Build and test
        run: |
          set -euo pipefail
          cargo new /tmp/benchs rust 2>/dev/null || rm -rf /tmp/benchs && cargo new /tmp/benchs
          cd /tmp/benchs
          cat >> Cargo.toml <<'TOML'
[profile.release]
lto = true
TOML
          cat > src/lib.rs <<'RS'
pub fn primes(n: usize) -> Vec<usize> {
    let mut sieve = vec![true; n + 1];
    let mut out = Vec::new();
    for i in 2..=n {
        if sieve[i] {
            out.push(i);
            let mut m = i * i;
            while m <= n { sieve[m] = false; m += i; }
        }
    }
    out
}
RS
          cat > src/main.rs <<'RS'
fn main() { println!("{}", benchs::primes(200000).len()); }
RS
          cat > tests/primes.rs <<'RS'
#[test]
fn primes_work() { assert_eq!(benchs::primes(30).len(), 10); }
RS
          cargo build --release
          cargo test --release
          ./target/release/benchs >/dev/null

